WITH flattened AS (SELECT id, host, log_ts, level, attr_key, value FROM app_logs LATERAL VIEW EXPLODE(context) t AS attr_key, value) SELECT id, host, log_ts, level, attr_key, value, ROW_NUMBER() OVER (PARTITION BY host ORDER BY log_ts, id, attr_key) AS seq_no, FIRST_VALUE(attr_key, TRUE) OVER (ORDER BY log_ts, id, attr_key ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_attr_key FROM flattened;
